import math


def normal_kl(mean, variance):
    if variance <= 0:
        raise ValueError("Variance must be positive")
    # KL(N(mean, variance) || N(0, 1)) for one latent coordinate.
    return 0.5 * (mean**2 + variance - math.log(variance) - 1)


print(normal_kl(0.0, 1.0), normal_kl(1.0, 1.0))
